cat > "$SRC/src/main/java/gg/laughtail/core/CombatTracker.java" <<'LT_SRC_EOF_src_main_java_gg_laughtail_core_CombatTracker_java'
package gg.laughtail.core;

import org.bukkit.Location;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.PlayerDeathEvent;

import java.nio.charset.StandardCharsets;
import java.sql.SQLException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Level;

/**
 * Records every player death as a combat_events row, with the reason it did or did not
 * count towards rating.
 *
 * WHAT THIS DOES NOT DO: calculate rating. Every row is written with rp_delta 0 and the
 * rating tables are untouched, because Appendix B contradicts Section 9 in three places
 * (questions.md Q-11 to Q-13) and 28.8 names ranking as the place where maximum care is
 * warranted. Writing a formula now would mean either guessing which of two contradictory
 * specifications is meant, or quietly inventing a third. The EVIDENCE is being collected
 * from the first kill onwards, so when the constants are settled the history is already
 * there - and row 31's diminishing-returns pattern can be validated against real data
 * rather than a synthetic test.
 *
 * WHY THE THRESHOLDS ARE NOT IN THIS FILE. Never-break rule 10: "Never publish detector
 * thresholds for anti-cheat, wagering, or market manipulation. Publishing them teaches
 * evasion." The repeat-kill window and the alt-detection settings are read at runtime from
 * a private config that is created on the host and never committed. The DETECTION LOGIC is
 * public and reviewable here; only the numbers are withheld, which is the right split -
 * a reviewer can check the logic is sound without learning where the line sits.
 *
 * SAME-IP HANDLING, and why it stores a hash. Row 32 requires same-IP kills to award zero
 * and raise an alert, which needs comparison, not readability. Storing the address itself
 * would put a personal identifier in a table that 31.13 governs for retention, for no
 * benefit - a hash compares exactly as well. The salt lives in the private config so the
 * hashes are not reversible with a rainbow table of the IPv4 space, which is small enough
 * to enumerate.
 */
final class CombatTracker implements Listener {

    private final LaughTailPlugin plugin;
    private final Database db;
    private final StatsTracker stats;

    /** Recent kills per (killer -> victim), newest first. Bounded, in memory only. */
    private final Map<String, Deque<Long>> recentKills = new ConcurrentHashMap<>();
    /** Current killstreak per player. Reset on death. */
    private final Map<UUID, Integer> streaks = new ConcurrentHashMap<>();

    // Read from the private config. Defaults here are deliberately NOT the operating
    // values - they are conservative placeholders so the plugin runs if the private file
    // is missing, and the log says loudly when that happens.
    private long repeatWindowMillis = 3_600_000L;
    private int repeatBeforeZero = 3;
    private String ipSalt = "";
    private boolean privateConfigLoaded = false;

    CombatTracker(LaughTailPlugin plugin, Database db, StatsTracker stats) {
        this.plugin = plugin;
        this.db = db;
        this.stats = stats;
    }

    void configure(long repeatWindowMillis, int repeatBeforeZero, String ipSalt, boolean loaded) {
        this.repeatWindowMillis = repeatWindowMillis;
        this.repeatBeforeZero = repeatBeforeZero;
        this.ipSalt = ipSalt;
        this.privateConfigLoaded = loaded;
        if (!loaded) {
            plugin.getLogger().warning(
                "Anti-farm thresholds are running on PLACEHOLDER defaults because the private "
              + "config was not found. Detection works but the numbers are not the operating "
              + "ones. See never-break rule 10 and docs/private/.");
        }
    }

    private String hashIp(Player p) {
        if (p.getAddress() == null || p.getAddress().getAddress() == null) return null;
        String raw = ipSalt + '|' + p.getAddress().getAddress().getHostAddress();
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] h = md.digest(raw.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(64);
            for (byte b : h) sb.append(String.format("%02x", b));
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            return null;   // SHA-256 is mandated by the JLS; this cannot happen
        }
    }

    /**
     * Decides whether a kill counts, and why not if it does not. Returns null when the
     * kill is legitimate.
     *
     * The order matters: cheapest and most certain checks first, so an obvious
     * self-inflicted death never reaches the alt-detection logic.
     */
    private String suppressionReason(Player killer, Player victim, boolean sameIp) {
        if (killer == null) return "no_killer";                       // environment or mob
        if (killer.getUniqueId().equals(victim.getUniqueId())) return "self_inflicted";
        if (sameIp) return "same_ip";                                  // row 32
        if (killer.hasPermission("laughtail.staff.chat")) return "staff_excluded";  // 17.4
        if (victim.hasPermission("laughtail.staff.chat")) return "staff_excluded";

        String key = killer.getUniqueId() + ">" + victim.getUniqueId();
        Deque<Long> q = recentKills.computeIfAbsent(key, k -> new ArrayDeque<>());
        long now = System.currentTimeMillis();
        synchronized (q) {
            while (!q.isEmpty() && now - q.peekLast() > repeatWindowMillis) q.pollLast();
            int recent = q.size();
            q.addFirst(now);
            // Bounded so a long session cannot grow this without limit.
            while (q.size() > 64) q.pollLast();
            if (recent >= repeatBeforeZero) return "repeat_kill";     // row 31
        }
        return null;
    }

    @EventHandler(priority = EventPriority.MONITOR)
    public void onDeath(PlayerDeathEvent e) {
        final Player victim = e.getEntity();
        final Player killer = victim.getKiller();

        boolean sameIp = false;
        String killerHash = null, victimHash = hashIp(victim);
        if (killer != null) {
            killerHash = hashIp(killer);
            sameIp = killerHash != null && killerHash.equals(victimHash);
        }

        final String reason = suppressionReason(killer, victim, sameIp);
        final boolean counted = (reason == null);

        // Streak bookkeeping happens whether or not the kill scores rating: 9.8 tracks
        // killstreak as a statistic, and a suppressed kill is still a kill.
        streaks.put(victim.getUniqueId(), 0);
        stats.recordDeath(victim.getUniqueId());
        if (killer != null && !killer.getUniqueId().equals(victim.getUniqueId())) {
            int s = streaks.merge(killer.getUniqueId(), 1, Integer::sum);
            stats.recordKill(killer.getUniqueId(), s, true);
        }

        if (sameIp) {
            // Row 32 wants an ALERT, not just a zero. There is no Discord webhook yet
            // (OA-16), so it goes to the console at WARNING where the monitor's
            // error-delta check will surface it within five minutes.
            plugin.getLogger().warning("ROW 32 ALERT: same-IP kill - "
                + (killer != null ? killer.getName() : "?") + " killed " + victim.getName()
                + ". Zero rating awarded. Investigate for alt farming.");
        }

        final Location loc = victim.getLocation();
        final UUID killerId = killer != null ? killer.getUniqueId() : null;
        final UUID victimId = victim.getUniqueId();
        final boolean sameIpFinal = sameIp;

        plugin.getServer().getScheduler().runTaskAsynchronously(plugin, () -> {
            try {
                db.recordCombatEvent(killerId, victimId, counted ? 0 : 0, 0,
                    reason, sameIpFinal,
                    loc.getWorld() != null ? loc.getWorld().getName() : null,
                    loc.getBlockX(), loc.getBlockY(), loc.getBlockZ());
            } catch (SQLException ex) {
                plugin.getLogger().log(Level.SEVERE,
                    "Could not record combat event: " + ex.getMessage());
            }
        });
    }

    boolean isPrivateConfigLoaded() {
        return privateConfigLoaded;
    }
}
LT_SRC_EOF_src_main_java_gg_laughtail_core_CombatTracker_java

# ---- src/main/java/gg/laughtail/core/Moderation.java ----
cat > "$SRC/src/main/java/gg/laughtail/core/Moderation.java" <<'LT_SRC_EOF_src_main_java_gg_laughtail_core_Moderation_java'
package gg.laughtail.core;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.player.AsyncPlayerPreLoginEvent;
import org.bukkit.event.player.AsyncPlayerChatEvent;

import java.sql.SQLException;
import java.util.List;
import java.util.UUID;
import java.util.logging.Level;

/**
 * Moderation: the punishment commands, their enforcement, and the audit trail.
 *
 * TWO ACCEPTANCE CRITERIA SHAPE THIS CLASS.
 *
 * 17.4 / 17.5 item 4: "All staff actions are logged, permanently, to the database... and
 * staff cannot delete these logs." The cannot-delete half is enforced by V2's triggers and
 * already proven. This is the are-they-logged half - and note that EVERY command path
 * writes an audit row, including the ones that fail validation, because "staff tried to ban
 * a player who does not exist" is exactly the kind of thing an audit should show. An audit
 * that only records successes is a record of intentions, not actions.
 *
 * Row 14 / 3.2: no purchasable advantage. Nothing here can be bought, and the permission
 * nodes come from the Section 17 ladder that LuckPerms already enforces - so a Helper
 * physically cannot issue a permanent ban regardless of what this code does.
 *
 * BAN ENFORCEMENT USES AsyncPlayerPreLoginEvent, deliberately. Rejecting at pre-login
 * happens before the player entity is created, so a banned player never loads chunks or
 * touches the world. Doing it on PlayerJoinEvent would work and would also mean the server
 * generates spawn chunks for someone it is about to eject - wasted work on a 2 vCPU box,
 * and a brief window where they exist in the world.
 *
 * THE PUBLISHED LADDER (14.4) IS NOT IMPLEMENTED HERE. These commands take an explicit
 * duration from staff rather than deriving one from an offence, because 14.4's ladder text
 * is owner-approved policy (OA-13) and inventing a ladder would be inventing policy. The
 * `rule_broken` column exists in V2 and is left NULL until the ladder is written.
 */
final class Moderation implements Listener {

    private final LaughTailPlugin plugin;
    private final Database db;

    Moderation(LaughTailPlugin plugin, Database db) {
        this.plugin = plugin;
        this.db = db;
    }

    // ---- enforcement ---------------------------------------------------------

    @EventHandler(priority = EventPriority.HIGH)
    public void onPreLogin(AsyncPlayerPreLoginEvent e) {
        // Already off the main thread - this event is async by design, which is why the
        // database call here needs no scheduler hop.
        try {
            String ban = db.activePunishmentReason(e.getUniqueId(), "ban");
            if (ban == null) ban = db.activePunishmentReason(e.getUniqueId(), "tempban");
            if (ban != null) {
                e.disallow(AsyncPlayerPreLoginEvent.Result.KICK_BANNED,
                    "You are banned from Laugh Tale.\n\n" + ban
                  + "\n\nAppeals: see the website.");
            }
        } catch (SQLException ex) {
            // FAIL OPEN, deliberately, and log loudly. The alternative - refusing every
            // login when the database is unreachable - would turn a database hiccup into a
            // total outage for paying players. A banned player getting in for a few minutes
            // is recoverable; locking out everyone is not.
            plugin.getLogger().log(Level.SEVERE,
                "Ban check failed for " + e.getName() + " - allowing the login. " + ex.getMessage());
        }
    }

    @SuppressWarnings("deprecation")
    @EventHandler(priority = EventPriority.LOWEST, ignoreCancelled = true)
    public void onChat(AsyncPlayerChatEvent e) {
        final Player p = e.getPlayer();
        try {
            String mute = db.activePunishmentReason(p.getUniqueId(), "mute");
            if (mute != null) {
                e.setCancelled(true);
                p.sendMessage(Component.text("You are muted: " + mute, NamedTextColor.RED));
            }
        } catch (SQLException ex) {
            plugin.getLogger().log(Level.WARNING, "Mute check failed: " + ex.getMessage());
        }
    }

    // ---- commands ------------------------------------------------------------

    /** Returns true if handled. */
    boolean handle(CommandSender sender, String cmd, String[] args) {
        switch (cmd) {
            case "warn":     return punish(sender, args, "warn",    "laughtail.punish.kick",        false, false);
            case "mute":     return punish(sender, args, "mute",    "laughtail.punish.mute.short",  true,  false);
            case "kick":     return punish(sender, args, "kick",    "laughtail.punish.kick",        false, false);
            case "tempban":  return punish(sender, args, "tempban", "laughtail.punish.tempban",     true,  false);
            case "ban":      return punish(sender, args, "ban",     "laughtail.punish.permban",     false, true);
            case "unmute":   return revoke(sender, args, "mute",    "laughtail.punish.mute.short");
            case "unban":    return revoke(sender, args, "ban",     "laughtail.punish.overturn");
            case "history":  return history(sender, args);
            default:         return false;
        }
    }

    private UUID senderId(CommandSender s) {
        return (s instanceof Player p) ? p.getUniqueId() : null;
    }

    private void auditAsync(CommandSender sender, String action, UUID target,
                            String targetName, String params) {
        final UUID sid = senderId(sender);
        final String sname = sender.getName();
        final String world = (sender instanceof Player p && p.getWorld() != null)
            ? p.getWorld().getName() : null;
        plugin.getServer().getScheduler().runTaskAsynchronously(plugin, () -> {
            try {
                db.audit(sid, sname, action, target, targetName, params, world);
            } catch (SQLException e) {
                // An unwritten audit row is a hole in the record, so this is SEVERE rather
                // than WARNING - the monitor's error-delta check will surface it.
                plugin.getLogger().log(Level.SEVERE, "AUDIT WRITE FAILED for '" + action
                    + "' by " + sname + ": " + e.getMessage());
            }
        });
    }

    private boolean punish(CommandSender sender, String[] args, String type,
                           String permission, boolean needsDuration, boolean permanent) {
        if (!sender.hasPermission(permission)) {
            sender.sendMessage(Component.text("You do not have permission for " + type + ".",
                NamedTextColor.RED));
            auditAsync(sender, type + ".denied", null, args.length > 0 ? args[0] : null,
                "permission " + permission + " missing");
            return true;
        }
        int minArgs = needsDuration ? 3 : 2;
        if (args.length < minArgs) {
            sender.sendMessage(Component.text("Usage: /" + type + " <player> "
                + (needsDuration ? "<duration e.g. 30m, 2h, 7d> " : "") + "<reason>",
                NamedTextColor.GRAY));
            return true;
        }

        final String targetName = args[0];
        final Long durationSeconds;
        final int reasonFrom;
        if (needsDuration) {
            Long d = parseDuration(args[1]);
            if (d == null) {
                sender.sendMessage(Component.text(
                    "Could not read '" + args[1] + "' as a duration. Use 30m, 2h or 7d.",
                    NamedTextColor.RED));
                return true;
            }
            durationSeconds = d;
            reasonFrom = 2;
        } else {
            durationSeconds = permanent ? null : 0L;
            reasonFrom = 1;
        }
        final String reason = String.join(" ", java.util.Arrays.copyOfRange(args, reasonFrom, args.length));

        plugin.getServer().getScheduler().runTaskAsynchronously(plugin, () -> {
            try {
                UUID target = db.uuidByName(targetName);
                if (target == null) {
                    plugin.getServer().getScheduler().runTask(plugin, () ->
                        sender.sendMessage(Component.text(
                            "No player called '" + targetName + "' has ever joined.",
                            NamedTextColor.RED)));
                    // Audited anyway: an attempt against an unknown name is worth seeing.
                    db.audit(senderId(sender), sender.getName(), type + ".unknown_target",
                        null, targetName, reason, null);
                    return;
                }

                Long dur = (durationSeconds != null && durationSeconds == 0L) ? null : durationSeconds;
                long id = db.insertPunishment(target, type, reason, null, senderId(sender), dur);
                db.audit(senderId(sender), sender.getName(), type, target, targetName,
                    "id=" + id + " duration=" + (dur == null ? "permanent" : dur + "s")
                    + " reason=" + reason, null);

                plugin.getServer().getScheduler().runTask(plugin, () -> {
                    sender.sendMessage(Component.text(
                        type + " recorded for " + targetName + " (#" + id + ").",
                        NamedTextColor.GREEN));
                    Player online = plugin.getServer().getPlayerExact(targetName);
                    if (online != null) {
                        switch (type) {
                            case "kick", "tempban", "ban" -> online.kick(Component.text(
                                (type.equals("kick") ? "Kicked: " : "Banned: ") + reason,
                                NamedTextColor.RED));
                            case "warn" -> online.sendMessage(Component.text(
                                "WARNING from staff: " + reason, NamedTextColor.YELLOW));
                            case "mute" -> online.sendMessage(Component.text(
                                "You have been muted: " + reason, NamedTextColor.RED));
                            default -> { }
                        }
                    }
                });
            } catch (SQLException ex) {
                plugin.getLogger().log(Level.SEVERE, "Punishment failed: " + ex.getMessage());
                plugin.getServer().getScheduler().runTask(plugin, () ->
                    sender.sendMessage(Component.text(
                        "The punishment was NOT saved - the database rejected it. Nothing was applied.",
                        NamedTextColor.RED)));
            }
        });
        return true;
    }

    private boolean revoke(CommandSender sender, String[] args, String type, String permission) {
        if (!sender.hasPermission(permission)) {
            sender.sendMessage(Component.text("You do not have permission.", NamedTextColor.RED));
            auditAsync(sender, "un" + type + ".denied", null,
                args.length > 0 ? args[0] : null, "permission " + permission + " missing");
            return true;
        }
        if (args.length < 1) {
            sender.sendMessage(Component.text("Usage: /un" + type + " <player> [reason]",
                NamedTextColor.GRAY));
            return true;
        }
        final String targetName = args[0];
        final String reason = args.length > 1
            ? String.join(" ", java.util.Arrays.copyOfRange(args, 1, args.length))
            : "no reason given";

        plugin.getServer().getScheduler().runTaskAsynchronously(plugin, () -> {
            try {
                UUID target = db.uuidByName(targetName);
                if (target == null) {
                    plugin.getServer().getScheduler().runTask(plugin, () ->
                        sender.sendMessage(Component.text("Unknown player.", NamedTextColor.RED)));
                    return;
                }
                boolean done = db.revokePunishment(target, type, senderId(sender), reason);
                db.audit(senderId(sender), sender.getName(), "un" + type, target, targetName,
                    "revoked=" + done + " reason=" + reason, null);
                plugin.getServer().getScheduler().runTask(plugin, () ->
                    sender.sendMessage(Component.text(done
                        ? ("Active " + type + " revoked for " + targetName + ".")
                        : ("No active " + type + " found for " + targetName + "."),
                        done ? NamedTextColor.GREEN : NamedTextColor.GRAY)));
            } catch (SQLException ex) {
                plugin.getLogger().log(Level.SEVERE, "Revoke failed: " + ex.getMessage());
            }
        });
        return true;
    }

    private boolean history(CommandSender sender, String[] args) {
        if (!sender.hasPermission("laughtail.punish.history")) {
            sender.sendMessage(Component.text("You do not have permission.", NamedTextColor.RED));
            return true;
        }
        if (args.length < 1) {
            sender.sendMessage(Component.text("Usage: /history <player>", NamedTextColor.GRAY));
            return true;
        }
        final String targetName = args[0];
        plugin.getServer().getScheduler().runTaskAsynchronously(plugin, () -> {
            try {
                UUID target = db.uuidByName(targetName);
                if (target == null) {
                    plugin.getServer().getScheduler().runTask(plugin, () ->
                        sender.sendMessage(Component.text("Unknown player.", NamedTextColor.RED)));
                    return;
                }
                List<String> rows = db.punishmentHistory(target, 20);
                // Viewing history is itself a staff action and is audited. 17.3 treats the
                // audit log as sensitive; reading someone's record is not a neutral act.
                db.audit(senderId(sender), sender.getName(), "history.view", target, targetName,
                    rows.size() + " rows", null);
                plugin.getServer().getScheduler().runTask(plugin, () -> {
                    sender.sendMessage(Component.text("Punishment history for " + targetName
                        + " (" + rows.size() + "):", NamedTextColor.GOLD));
                    if (rows.isEmpty()) {
                        sender.sendMessage(Component.text("  clean record", NamedTextColor.GRAY));
                    }
                    for (String r : rows) {
                        sender.sendMessage(Component.text("  " + r, NamedTextColor.GRAY));
                    }
                });
            } catch (SQLException ex) {
                plugin.getLogger().log(Level.SEVERE, "History failed: " + ex.getMessage());
            }
        });
        return true;
    }

    /** Parses 30s, 30m, 2h, 7d. Returns null when unreadable rather than guessing. */
    static Long parseDuration(String s) {
        if (s == null || s.length() < 2) return null;
        char unit = s.charAt(s.length() - 1);
        String num = s.substring(0, s.length() - 1);
        long n;
        try {
            n = Long.parseLong(num);
        } catch (NumberFormatException e) {
            return null;
        }
        if (n <= 0) return null;
        return switch (unit) {
            case 's' -> n;
            case 'm' -> n * 60;
            case 'h' -> n * 3600;
            case 'd' -> n * 86400;
            default -> null;
        };
    }
}
LT_SRC_EOF_src_main_java_gg_laughtail_core_Moderation_java

echo "=== source staged ==="
find "$SRC/src" "$SRC/pom.xml" -type f | sort | while read -r f; do
  echo "  $(wc -l < "$f" | tr -d " ") lines  ${f#$SRC/}"
done

echo "=== is the image present, and is it the right architecture? ==="
sudo -n docker pull "$IMAGE" 2>&1 | tail -2
sudo -n docker inspect "$IMAGE" --format 'arch={{.Architecture}}'

echo "=== compiling ==="
# --memory 640m: this box has roughly 300 MB spare with the server running
# (baselines.md B3), so an unbounded maven JVM could push the host into OOM and
# take the game server with it. Capped deliberately, and the cap is generous
# enough for a six-file project.
#
# The .m2 cache is mounted so a rebuild does not re-download the world - the
# first build fetches Paper API and the MariaDB driver, later ones do not.
set +e
sudo -n docker run --rm \
  --memory 640m --memory-swap 640m \
  --cpus 1.5 \
  -u "$(id -u ubuntu):$(id -g ubuntu)" \
  -e HOME=/var/maven \
  -e MAVEN_CONFIG=/var/maven/.m2 \
  -v "$SRC":/src \
  -v "$M2":/var/maven/.m2 \
  -w /src \
  "$IMAGE" mvn -B -q -DskipTests -Dmaven.repo.local=/var/maven/.m2/repository package 2>&1 | tail -30
RC=${PIPESTATUS[0]}
set -e
echo "maven exit: $RC"
if [ "$RC" -ne 0 ]; then
  echo "BUILD FAILED - installing nothing."
  exit 3
fi

JAR="$SRC/target/LaughTail-$VERSION.jar"
if [ ! -s "$JAR" ]; then
  echo "BUILD REPORTED SUCCESS BUT THERE IS NO JAR - refusing to continue."
  ls -la "$SRC/target" 2>/dev/null | head
  exit 4
fi
echo "=== built ==="
ls -l "$JAR" | sed 's/^/  /'
sha256sum "$JAR" | sed 's/^/  /'

echo "=== the jar must contain the plugin descriptor and the shaded driver ==="
# `jar tf`, not `unzip -l`: the maven image ships a JDK but no unzip, and the
# first version of this check died on that after a successful build.
sudo -n docker run --rm -v "$SRC":/src -w /src "$IMAGE" \
  sh -c "jar tf target/LaughTail-$VERSION.jar | grep -E '^plugin.yml$|^config.yml$|LaughTailPlugin.class|RulesGate.class|Database.class|gg/laughtail/libs/mariadb/' | head -8"
echo "--- driver classes shaded and relocated: ---"
sudo -n docker run --rm -v "$SRC":/src -w /src "$IMAGE" \
  sh -c "jar tf target/LaughTail-$VERSION.jar | grep -c '^gg/laughtail/libs/mariadb/'"
echo "--- and NO unrelocated org/mariadb (0 expected, or the relocation silently failed): ---"
sudo -n docker run --rm -v "$SRC":/src -w /src "$IMAGE" \
  sh -c "jar tf target/LaughTail-$VERSION.jar | grep -c '^org/mariadb/' || true"

echo "=== installing into the server ==="
# The old jar is replaced, not left beside the new one - two versions of the
# same plugin in plugins/ is a load-order coin toss.
sudo -n rm -f "$D/plugins"/LaughTail-*.jar
sudo -n cp "$JAR" "$D/plugins/LaughTail-$VERSION.jar"
sudo -n chown $OWN "$D/plugins/LaughTail-$VERSION.jar"
sudo -n chmod 644 "$D/plugins/LaughTail-$VERSION.jar"
sudo -n ls -l "$D/plugins" | grep -i laughtail | sed 's/^/  /'

echo "=== disk after ==="
df -h --output=avail,pcent / | tail -1
sudo -n du -sh "$M2" 2>/dev/null | sed 's/^/  maven cache /'
echo "PLUGIN BUILT AND INSTALLED"
echo "=== END ==="
